def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_d = 0
    my_d = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1
        if a == 'D':
            my_d += 1
    opp_c = n - opp_d

    if opp_d == n:
        return 'D'

    recent10_defs = 0
    start_recent = n - 10
    if start_recent < 0:
        start_recent = 0
    for i in range(start_recent, n):
        if history[i][1] == 'D':
            recent10_defs += 1

    run_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            run_c += 1
        else:
            break

    run_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            run_d += 1
        else:
            break

    my_recent_D = 0
    start3 = n - 3
    if start3 < 0:
        start3 = 0
    for i in range(start3, n):
        if history[i][0] == 'D':
            my_recent_D += 1

    trans_t = [[0, 0], [0, 0]]
    trans_c = [[0, 0], [0, 0]]
    for i in range(1, n):
        pm = 0 if history[i - 1][0] == 'C' else 1
        po = 0 if history[i - 1][1] == 'C' else 1
        trans_t[pm][po] += 1
        if history[i][1] == 'C':
            trans_c[pm][po] += 1

    d_total = trans_t[1][0] + trans_t[1][1]
    d_success = trans_c[1][0] + trans_c[1][1]

    if run_d >= 5:
        return 'D'
    if n >= 8 and recent10_defs >= 8:
        return 'D'
    if opp_d * 2 > n and recent10_defs >= 5 and run_d >= 2:
        return 'D'

    if last_opp == 'C' and run_c >= 12 and recent10_defs <= 1 and opp_d <= (2 if n <= 20 else n // 10):
        if d_total == 0:
            if last_my == 'C':
                return 'D'
        elif d_success > 0:
            if d_success == d_total:
                if not (d_total == 1 and d_success == 1 and opp_d > 0 and run_c < 15):
                    return 'D'
            elif d_total <= 3 and d_success >= 2:
                return 'D'
            elif d_success * 3 >= d_total * 2:
                return 'D'

    remaining = 100 - n
    if remaining <= 8:
        overall_coop = opp_c / float(n)
        myC_total = trans_t[0][0] + trans_t[0][1]
        myC_success = trans_c[0][0] + trans_c[0][1]

        p = [0.0, 0.0, 0.0, 0.0]
        for mi in (0, 1):
            for oi in (0, 1):
                idx = mi * 2 + oi
                t = trans_t[mi][oi]
                s = trans_c[mi][oi]

                if t > 0:
                    val = (s + 1.0) / (t + 2.0)
                else:
                    if mi == 0:
                        if myC_total > 0:
                            val = (myC_success + 2.0 * (0.9 if overall_coop >= 0.7 else 0.6)) / (myC_total + 4.0)
                        else:
                            val = 0.9 if overall_coop >= 0.7 else 0.6
                    else:
                        if d_total > 0:
                            val = (d_success + 2.0 * (0.25 if overall_coop >= 0.8 else 0.10)) / (d_total + 4.0)
                        else:
                            val = 0.25 if overall_coop >= 0.8 else 0.10

                if mi == 1:
                    if d_total == 0:
                        if val > 0.22:
                            val = 0.22
                    elif d_total == 1:
                        if d_success == 0:
                            if val > 0.30:
                                val = 0.30
                        else:
                            if val > 0.60:
                                val = 0.60
                    elif d_total < 4:
                        if val > 0.70:
                            val = 0.70

                    if run_d >= 3:
                        if val > 0.15:
                            val = 0.15
                    elif recent10_defs >= 4:
                        if val > 0.40:
                            val = 0.40
                    if opp_d * 2 > n:
                        if val > 0.35:
                            val = 0.35
                else:
                    if run_d >= 3:
                        if val > 0.55:
                            val = 0.55
                    elif recent10_defs >= 6:
                        if val > 0.30:
                            val = 0.30
                    if opp_d * 3 > n * 2:
                        if val > 0.40:
                            val = 0.40

                if val < 0.0:
                    val = 0.0
                elif val > 1.0:
                    val = 1.0
                p[idx] = val

        start_idx = (0 if last_my == 'C' else 1) * 2 + (0 if last_opp == 'C' else 1)

        val = [0.0, 0.0, 0.0, 0.0]
        act = [0, 0, 0, 0]

        for _ in range(1, remaining + 1):
            new_val = [0.0, 0.0, 0.0, 0.0]
            new_act = [0, 0, 0, 0]
            for sidx in range(4):
                prob = p[sidx]

                vc = 3.0 * prob + (prob * val[0] + (1.0 - prob) * val[1])
                vd = (1.0 + 4.0 * prob) + (prob * val[2] + (1.0 - prob) * val[3])

                if vd > vc + 0.05:
                    new_val[sidx] = vd
                    new_act[sidx] = 1
                else:
                    new_val[sidx] = vc
                    new_act[sidx] = 0

            val = new_val
            act = new_act

        if act[start_idx] == 1:
            return 'D'
        return 'C'

    if last_opp == 'C':
        return 'C'

    if my_recent_D > 0 and run_d <= 2 and recent10_defs <= 4 and opp_d * 2 < n:
        return 'C'

    if last_my == 'D':
        if run_d <= 2 and recent10_defs <= 4 and opp_d * 3 <= n:
            return 'C'
        if my_recent_D > 0 and run_d >= 3 and (n % 7 == 0) and recent10_defs <= 5 and opp_d * 2 <= n:
            return 'C'
        return 'D'

    return 'D'
